insert into public.emergency_meta (id, note_en, note_ka, note_ru, national_number, national_number_description_en, national_number_description_ka, national_number_description_ru, health_hotline_number, health_hotline_description_en, health_hotline_description_ka, health_hotline_description_ru, tourist_info_name_en, tourist_info_address, tourist_info_hours, tourist_info_description_en, tourist_info_description_ka, tourist_info_description_ru) values
  (1, 'Contact details compiled from public sources, July 2026. Verify critical numbers before relying on them in a real emergency — always call 112 first.', 'საკონტაქტო დეტალები შედგენილია საჯარო წყაროებიდან, 2026 წლის ივლისი. გადამოწმე კრიტიკული ნომრები რეალურ საგანგებო სიტუაციაში მათზე დაყრდნობამდე — ყოველთვის ჯერ დარეკე 112-ზე.', 'Контактные данные собраны из открытых источников, июль 2026 года. Проверяйте важные номера перед тем, как полагаться на них в реальной чрезвычайной ситуации — всегда сначала звоните 112.', '112', 'Single emergency number in Georgia for police, fire, and ambulance. Free from any phone, available 24/7, English-speaking operators available.', 'საქართველოში ერთიანი საგანგებო ნომერი პოლიციის, სახანძრო და სასწრაფო დახმარებისთვის. უფასოა ნებისმიერი ტელეფონიდან, ხელმისაწვდომია 24/7, არის ინგლისურენოვანი ოპერატორები.', 'Единый номер экстренных служб в Грузии для полиции, пожарной службы и скорой помощи. Бесплатный с любого телефона, доступен круглосуточно, есть англоговорящие операторы.', '1505', 'Georgia Ministry of Health 24/7 hotline for medical guidance and information.', 'საქართველოს ჯანდაცვის სამინისტროს 24/7 ცხელი ხაზი სამედიცინო რჩევებისა და ინფორმაციისთვის.', 'Круглосуточная горячая линия Министерства здравоохранения Грузии для медицинских консультаций и информации.', 'Tbilisi Tourist Information Center', '3 Rustaveli Ave, Tbilisi', '10:00-18:00 daily', 'Free maps, directions, and non-emergency tourist assistance. Not a police station — for emergencies always call 112.', 'უფასო რუკები, მიმართულებები და არასაგანგებო ტურისტული დახმარება. არ არის პოლიციის განყოფილება — საგანგებო სიტუაციებისთვის ყოველთვის დარეკე 112-ზე.', 'Бесплатные карты, указания и неэкстренная помощь туристам. Это не полицейский участок — в экстренных случаях всегда звоните 112.')
insert into public.emergency_police (id, name_en, address, phone, description_en, description_ka, description_ru) values
  ('patrol_police', 'Patrol Police Hotline', NULL, '+995 32 241 42 42', 'General patrol police assistance line for non-emergency police matters.', 'პატრულირების პოლიციის ზოგადი დახმარების ხაზი არასაგანგებო პოლიციის საკითხებისთვის.', 'Общая линия помощи патрульной полиции по неэкстренным полицейским вопросам.'),
  ('mia_hq', 'Ministry of Internal Affairs (HQ)', '4 Gmiri Kursantebi St, Tbilisi', '+995 32 241 26 64', 'Main Ministry of Internal Affairs contact office.', 'შინაგან საქმეთა სამინისტროს მთავარი საკონტაქტო ოფისი.', 'Главный контактный офис Министерства внутренних дел.'),
  ('old_tbilisi_district_police', 'Old Tbilisi District Police Main Department', '27 Tabukashvili St, Tbilisi', NULL, 'Local police department covering the Old Town tourist area.', 'ადგილობრივი პოლიციის დეპარტამენტი, რომელიც მოიცავს ძველი ქალაქის ტურისტულ ზონას.', 'Местный полицейский департамент, обслуживающий туристическую зону Старого города.')
insert into public.emergency_hospitals (id, name_en, address, phone, lat, lng, notes_en, notes_ka, notes_ru) values
  ('amc_vake', 'American Medical Centers (AMC) Vake', '11 Dimitri Arakishvili St, Vake, Tbilisi 0179', '+995 32 250 00 20', 41.715, 44.756, '24/7 emergency care, English-speaking staff, direct billing with many international insurers.', '24/7 გადაუდებელი დახმარება, ინგლისურენოვანი პერსონალი, პირდაპირი ანგარიშსწორება ბევრ საერთაშორისო სადაზღვევო კომპანიასთან.', 'Круглосуточная неотложная помощь, англоговорящий персонал, прямые расчёты со многими международными страховщиками.'),
  ('republican_hospital', 'Academic N. Kipshidze University Clinic - Republican Hospital', '29 Vazha-Pshavela Ave, Tbilisi', '+995 32 224 40 33', 41.726, 44.75, 'Major multi-profile hospital with emergency department.', 'დიდი მრავალპროფილური საავადმყოფო გადაუდებელი დახმარების განყოფილებით.', 'Крупная многопрофильная больница с отделением неотложной помощи.'),
  ('eristavi_center', 'K. Eristavi National Experimental and Clinical Surgery Center', '5 Chachava St, Tbilisi', '+995 32 202 25 25', 41.719, 44.752, 'Emergency and surgical care center.', 'გადაუდებელი და ქირურგიული დახმარების ცენტრი.', 'Центр неотложной и хирургической помощи.')
